    "assert tmux_format(True, timedelta(days=-1)) == '#[noreverse,fg=black,bg=green] HB  '",
    "assert tmux_format(False, timedelta(days=-1)) == '#[reverse,fg=colour1,bg=white] GW  '"
  ]
