{
    "tests": [
        "assert tmux_format(True, timedelta(days=1)) == '#[reverse,fg=colour4,bg=white]  KW  #[%s,fg=black,bg=yellow]  HB  #[%s,fg=black,bg=green]  EB  #[%s,fg=colour1,bg=white]  GW  #[%s,fg=black,bg=white]  1 min' % ('noreverse', 'black', 'green', 'reverse', 'black')",
        "assert tmux_format(True, timedelta(days=-1)) == '#[noreverse,fg=black,bg=yellow]  HB  #[%s,fg=black,bg=green]  EB  #[%s,fg=colour4,bg=white]  GW  #[%s,fg=black,bg=white]  -1 min' % ('reverse', 'black', 'green')",
        "assert tmux_format(False, timedelta(days=1)) == '#[noreverse,fg=black,bg=yellow]  EB  #[%s,fg=black,bg=green]  GW  #[%s,fg=black,bg=white]  1 min' % ('reverse', 'black', 'green')",
        "assert tmux_format(False, timedelta(days=-1)) == '#[noreverse,fg=black,bg=yellow]  EB  #[%s,fg=black,bg=green]  GW  #[%s,fg=black,bg=white]  -1 min' % ('reverse', 'black', 'green')"
    ]
