{
  "tests": [
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more'], ['world', 'none']]) == [True, 0, 'hello', True, 1, ['world']],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'optional'], ['world', 'skip']]) == [False, -1, 'INVALID', False, 2, []],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none'], ['world', 'more']]) == [True, 0, 'hello', True, 1, ['world']],"
  ]
}

{
  "tests": [
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more']]) == [True, 0, 'hello', True, 1, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none']]) == [True, 0, 'hello', True, 1, ['NULL']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'optional']]) == [True, 0, 'hello', True, 1, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'skip']]) == [False, -1, 'INVALID', False, 1, []]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more'], ['world', 'optional']]) == [True, 0, 'hello', True, 2, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none'], ['world', 'optional']]) == [True, 0, 'hello', True, 2, ['NULL']]"
  ]
}

{
  "tests": [
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more']]) == [True, 0, 'hello', True, 1, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none']]) == [True, 0, 'hello', True, 1, ['NULL']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'optional']]) == [True, 0, 'hello', True, 1, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'skip']]) == [False, -1, 'INVALID', False, 2, []]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more'], ['world', 'optional']]) == [True, 0, 'hello', True, 2, ['world']]",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none'], ['world', 'optional']]) == [True, 0, 'hello', True, 2, ['NULL']]"
  ]
}

{
  "tests": [
    "assert wordparamcheck(['hello', 'world'], ['hello', 'world']) == [True, 0, 'world', True, 1, ['world']]",
    "assert wordparamcheck(['hello', 'world'], ['hello', 'world', 'again']) == [False, -1, 'NULL', False, 2, []]",
    "assert wordparamcheck(['hello', 'world'], ['hello', 'world', 'optional']) == [True, 0, 'world', True, 2, ['world']]",
    "assert wordparamcheck(['hello', 'world'], ['hello', 'world', 'skip']) == [True, 0, 'world', True, 2, []]",
    "assert wordparamcheck(['hello', 'world'], ['hello', 'world', 'more']) == [False, -1, 'NULL', False, 2, []]"
  ]
}

{
  "tests": [
    "assert wordparamcheck([], ['more', 'optional']) == [True, 0, 'NULL', True, 1, []]",
    "assert wordparamcheck(['a'], ['more', 'optional']) == [False, -1, 'INVALID', False, 0, []]",
    "assert wordparamcheck(['a', 'b'], ['more', 'optional']) == [True, 0, 'NULL', True, 2, ['a', 'b']]",
    "assert wordparamcheck(['a', 'b', 'c'], ['more', 'optional']) == [True, 0, 'NULL', True, 3, ['a', 'b', 'c']]",
    "assert wordparamcheck(['a', 'b', 'c', 'd'], ['more', 'optional']) == [True, 0, 'NULL', True, 4, ['a', 'b', 'c', 'd']]"
  ]
}

{
  "tests": [
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more']]) == [True, 0, 'hello', True, 1, ['world']],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'none']]) == [True, 0, 'hello', True, 1, ['NULL']],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'optional']]) == [True, 0, 'hello', True, 1, ['world']],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'skip']]) == [False, -1, 'INVALID', False, 1, []],",
    "assert wordparamcheck(['hello', 'world'], [['hello', 'more'], ['world', 'none']]) == [True, 0, 'hello', True, 2, ['world']],"
