            "assertion": "assert circle_line_intersection((1, 2), 3, (0, 0), (4, 4), full_line=False) == [(2.5, 2.5)]",
            "description": "Circle intersects the line segment at one point without considering the full line."
        },
        {
            "assertion": "assert circle_line_intersection((1, 2), 3, (0, 0), (4, 4), tangent_tol=0) == [(2.5, 2.5)]",
            "description": "Circle intersects the line segment at one point with a very small tolerance."
        }
    ]
}

{
    "tests": [
        {
            "assertion": "assert circle_line_intersection((1, 1), 2, (0, 0), (3, 4)) == [(1.5, 1.5)]",
            "description": "Test for a single intersection point."
        },
        {
            "assertion": "assert circle_line_intersection((1, 1), 2, (0, 0), (3, 4), full_line=False) == [(1.5, 1.5)]",
            "description": "Test for a single intersection point when considering only the segment."
