    ]
}

{
  "tests": [
    "assert checkFormulas({}, [('a',)], {}) == False",
    "assert checkFormulas({'a': 1}, [('a',)], {}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': 1}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 3)], {'a': 1}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('c',)], {'a': 1}) == False"
  ]
}

