    "assert unmet_compare({'a': ['b', 'c']}, {'a': ['d']}) == (PKG_TRADED_UNMET, 'Package a gained new dependency d ')"
  ]
}

{
  "tests": [
    "assert unmet_compare({'a': ['b']}, {'a': ['c']}) == (PKG_NEW_UNMET, 'Package a gained new dependency b')",
    "assert unmet_compare({'a': ['b', 'c']}, {'a': ['d']}) == (NEW_PKG, 'New packages with dependency problems 
	 b
	d')",
    "assert unmet_compare({'a': ['b']}, {'a': ['b']}) == (NO_NEW, 'No new dependency problems')"
  ]
}

{
  "tests": [
    {
      "assertion": "unmet_compare({'a': ['b']}, {'a': ['c'], 'b': ['d']}) == (NEW_PKG, 'New packages with dependency problems 
	 b depends on d ')",
      "reason": "The new package 'b' has a new dependency 'd', which is not present in the current dependencies."
    },
    {
      "assertion": "unmet_compare({'a': ['b']}, {'a': ['c'], 'b': ['e']}) == (PKG_NEW_UNMET, 'Package b gained new dependency e ')",
      "reason": "The package 'b' has a new dependency 'e', which is not present in the current dependencies."
    },
    {
      "assertion": "unmet_compare({'a': ['b']}, {'a': ['c'], 'b': ['f']}) == (PKG_TRADED_UNMET, 'Package b swapped unmet dependencies
	gained f
	lost b')",
      "reason": "The package 'b' has a new dependency 'f', which is not present in the current dependencies. It also lost its original dependency 'b'."
    }
  ]
}

{
  "tests": [
