    "assert unmet_compare({'pkg1': ['dep1', 'dep2']}, {'pkg1': ['dep3'], 'pkg2': ['dep4']}) == (NO_NEW, 'No new dependency problems')"
  ]
}

{
  "tests": [
    "assert unmet_compare({'a': ['b', 'c']}, {'a': ['d'], 'b': ['e']}) == (NO_NEW, 'No new dependency problems')",
    "assert unmet_compare({'a': ['b', 'c']}, {'a': ['d'], 'b': ['f']}) == (PKG_TRADED_UNMET, 'Package a gained new dependency f ')",
