  ]
}

{
  "tests": [
    "assert char_span_to_token_span([], (0, 0)) == ((0, 0), False)",
    "assert char_span_to_token_span([(0, 3)], (1, 2)) == ((0, 3), False)",
    "assert char_span_to_token_span([(0, 3)], (0, 4)) == ((0, 3), True)",
    "assert char_span_to_token_span([(0, 3), (5, 8)], (1, 2)) == ((0, 3), False)",
    "assert char_span_to_token_span([(0, 3), (5, 8)], (4, 6)) == ((0, 3), True)"
  ]
}

{
    "tests": [
        {
            "assertion": "char_span_to_token_span([(0, 1)], (0, 1)) == ((0, 1), False)",
            "description": "Test case where character span matches exactly with token span."
        },
        {
            "assertion": "char_span_to_token_span([(0, 2)], (0, 1)) == ((0, 1), True)",
            "description": "Test case where character span starts before the first token ends."
        },
        {
            "assertion": "char_span_to_token_span([(0, 2)], (1, 3)) == ((0, 1), False)",
            "description": "Test case where character span ends after the last token starts."
        }
    ]
}

{
    "tests": [
        "assert char_span_to_token_span([], (0, 0)) == ((-1, -1), False)",
        "assert char_span_to_token_span([(0, 5)], (2, 4)) == ((1, 3), False)",
        "assert char_span_to_token_span([(0, 5)], (0, 6)) == ((0, 5), True)",
        "assert char_span_to_token_span([(0, 5)], (5, 7)) == ((2, 4), True)",
        "assert char_span_to_token_span([(0, 5)], (8, 10)) == ((-1, -1), True)"
    ]
}

{
  "tests": [
    "assert char_span_to_token_span([], (0, 0)) == ((0, 0), False)",
    "assert char_span_to_token_span([(1, 2)], (0, 0)) == ((0, 0), True)",
    "assert char_span_to_token_span([(1, 2)], (1, 3)) == ((1, 2), False)",
    "assert char_span_to_token_span([(1, 2)], (2, 4)) == ((1, 2), False)",
    "assert char_span_to_token_span([(1, 2), (3, 4)], (0, 5)) == ((0, 2), False)"
  ]
}

{
  "tests": [
    "assert char_span_to_token_span([], (0, 0)) == ((0, 0), False)",
    "assert char_span_to_token_span([(1, 2)], (0, 0)) == ((0, 0), True)",
    "assert char_span_to_token_span([(1, 2)], (1, 3)) == ((1, 2), False)",
    "assert char_span_to_token_span([(1, 2)], (1, 4)) == ((1, 2), False)",
    "assert char_span_to_token_span([(1, 2)], (0, 1)) == ((0, 1), True)"
  ]
}

{
  "tests": [
    {
      "assertion": "areas_not_covered([[1, 5]], 10) == [[1, 5]]",
      "reason": "The first contig covers the entire genome."
    },
    {
      "assertion": "areas_not_covered([[2, 6]], 10) == [[2, 6]]",
      "reason": "The second contig covers the entire genome."
    },
    {
      "assertion": "areas_not_covered([[3, 7]], 10) == [[3, 7]]",
      "reason": "The third contig covers the entire genome."
    }
  ]
}

{
  "tests": [
    {
      "assertion": "len(areas_not_covered([], 10)) == 0",
      "description": "Empty list of contigs should return an empty list"
    },
    {
      "assertion": "areas_not_covered([[1, 5]], 10) == [[1, 5]]",
      "description": "Single contig covering the entire genome should be returned as is"
    },
    {
      "assertion": "areas_not_covered([[2, 4], [6, 8]], 10) == [[2, 3], [4, 5], [6, 7]]",
      "description": "Multiple contigs covering different parts of the genome should be returned as is"
    },
    {
      "assertion": "areas_not_covered([[1, 5], [6, 8]], 10) == [[2, 3], [4, 5], [6, 7]]",
      "description": "Multiple overlapping contigs covering different parts of the genome should be returned as is"
    },
    {
      "assertion": "areas_not_covered([[1, 5], [6, 8]], 10) == [[2, 3], [4, 5], [6, 7]]",
      "description": "Multiple overlapping contigs covering different parts of the genome should be returned as is"
    }
  ]
}

