{
"tests": [
"assert checkFormulas({'a': 1}, [('a',)], {'a': 1}) == True",
"assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': 1, 'b': 2}) == True",
"assert checkFormulas({'a': 1}, [('c',)], {'a': 1}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': 1, 'b': 3}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': 1, 'b': 2}) == True"
]
}

{
"tests": [
"assert checkFormulas({'a': 1}, [('a',)], {'a': 1}) == True",
"assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': 1, 'b': 2}) == True",
"assert checkFormulas({'a': 1, 'b': 2}, [('c',)], {'a': 1, 'b': 2}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {1: 2}}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {(1, 2): 3}}) == True"
]
}

{
"tests": [
"assert checkFormulas({'a': 1}, [('a',)], {'a': 1}) == True",
"assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': 1, 'b': 2}) == True",
"assert checkFormulas({'a': 1}, [('c',)], {'a': 1}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('c',)], {'a': 1, 'b': 2}) == False",
"assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {('b',): 3}}) == True"
]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': set(), 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {2}}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {2}, 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'c')], {'a': {1}, 'b': set(), 'c': set()}) == False"
  ]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': set(), 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {('a', 'b')}, 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'c')], {'a': set(), 'b': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b'), ('c',)], {'a': {('a', 'b')}, 'b': set(), 'c': set()}) == True"
  ]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': set(), 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {('a', 'b')}, 'b': set()}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'c')], {'a': set(), 'b': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b'), ('b',)], {'a': {('a', 'b')}, 'b': set()}) == True"
  ]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': 1}) == True",
    "assert checkFormulas({'a': 1}, [('b',)], {'a': 1}) == False",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'b')], {'a': {'b': 2}}) == True",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'c')], {'a': {'b': 2}}) == False",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'b', 3)], {'a': {'b': 2}}) == False"
  ]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': set()}) == False",
    "assert checkFormulas({'a': 1}, [('a',)], {'a': {1}}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': set(), 'b': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a',), ('b',)], {'a': {1}, 'b': {2}}) == True",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': set(), 'b': set()}) == False",
    "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b')], {'a': {1}, 'b': {2}}) == True"
  ]
}

{
  "tests": [
    "assert checkFormulas({'a': 1}, [('a',)], {'a': 1}) == True",
    "assert checkFormulas({'a': 1}, [('b',)], {'a': 1}) == False",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'b')], {'a': {'b': 2}}) == True",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'c')], {'a': {'b': 2}}) == False",
    "assert checkFormulas({'a': {'b': 2}}, [('a', 'b', 3)], {'a': {'b': 2}}) == False"
  ]
}

