{
  "tests": [
    "assert updateRHS('velocity', 'u') == 'rhs(i,j,k,indvars(rhs_x)) = u'",
    "assert updateRHS('pressure', 'p', update=True) == 'rhs(i,j,k,indvars(rhs_y)) = rhs(i,j,k,indvars(rhs_y)) + p'",
    "assert updateRHS('temperature', 'T', i='x', j='y', k='z') == 'rhs(x,y,z,indvars(rhs_z)) = T'",
    "assert updateRHS('velocity', 'v', updateq=True) == 'q(i,j,k,indvars(rhs_x)) = v'",
    "assert updateRHS('pressure', 'q', i='m', j='n') == 'rhs(m,n,indvars(rhs_y)) = rhs(m,n,indvars(rhs_y)) + q'"
  ]
}

{
  "tests": [
