    "assert updateRHS('pressure', 'p', update=True) == 'rhs(i,j,k,indvars(rhs_y)) = rhs(i,j,k,indvars(rhs_y)) + p'",
    "assert updateRHS('temperature', 'T', i='x', j='y', k='z') == 'rhs(x,y,z,indvars(rhs_z)) = T'",
    "assert updateRHS('velocity', 'v', updateq=True) == 'q(i,j,k,indvars(rhs_x)) = q(i,j,k,indvars(rhs_x)) + v'",
    "assert updateRHS('pressure', 'q', dim=2) == 'rhs(i,j,indvars(rhs_y)) = q(i,j,indvars(rhs_y))'"
  ]
}

