{
  "tests": [
    "assert single_defcom_extract(0, ['def example():', '    """This is a docstring."""']) == '    """This is a docstring."""'",
    "assert single_defcom_extract(1, ['class MyClass:', '    def my_method(self):', '        '''Method docstring.'''']) == '        '''Method docstring.''''",
    "assert single_defcom_extract(0, ['def example():', '    # This is a comment', '    pass']) == ''",
    "assert single_defcom_extract(2, ['class MyClass:', '    def my_method(self):', '        # This is a comment', '        pass']) == ''",
    "assert single_defcom_extract(0, ['def example():', '    """This is a docstring.', '    It spans multiple lines."""']) == '    """This is a docstring.\n    It spans multiple lines."""'"
  ]
}

{
  "tests": [
    "assert single_defcom_extract(0, ['def foo():', '    """This is a docstring."""', '    pass']) == '    This is a docstring.'",
    "assert single_defcom_extract(1, ['class Bar:', '    def baz(self):', '        '''Another docstring here.'', '        pass']) == '        Another docstring here.'",
    "assert single_defcom_extract(0, ['def qux():', '    # This is not a docstring', '    pass']) == ''",
    "assert single_defcom_extract(2, ['class Foo:', '    def bar(self):', '        '''Start of comment', '           End of comment'''] == '        Start of comment\n           End of comment'",
    "assert single_defcom_extract(0, ['def spam():', '    """First line', 'Second line"""', '    pass']) == '    First line\nSecond line'"
  ]
}

{
  "tests": [
    "assert single_defcom_extract(0, ['def example():', '    """This is a docstring."""']) == '    This is a docstring.'",
    "assert single_defcom_extract(1, ['class MyClass:', '    def my_method(self):', '        '''Method docstring.'']) == '        Method docstring.'",
    "assert single_defcom_extract(0, ['def example():', '    # This is not a docstring', '    pass']) == ''",
    "assert single_defcom_extract(2, ['def first_method():', '    pass', 'def second_method():', '    '''This is the docstring for second_method.'']) == '    This is the docstring for second_method.'",
    "assert single_defcom_extract(0, ['class MyClass:', '    def __init__(self):', '        """Constructor docstring."""']) == '        Constructor docstring.'"
  ]
}

{
  "tests": [
    "assert single_defcom_extract(0, ['def example():', '    """This is a docstring."""', '    pass']) == '    """This is a docstring."""'",
