    "assert single_defcom_extract(1, ['class MyClass:', '    def my_method(self):', '        '''Method docstring.'', '        pass']) == '        Method docstring.'",
    "assert single_defcom_extract(0, ['def example():', '    # This is a comment', '    pass']) == ''",
    "assert single_defcom_extract(2, ['def first():', '    pass', 'def second():', '    """Second method docstring."""', '    pass']) == '    Second method docstring.'",
    "assert single_defcom_extract(0, ['class MyClass:', '    def __init__(self):', '        '''Constructor docstring.'', '        self.value = 0']) == '        Constructor docstring.'"
  ]
}

