{
  "tests": [
    "assert remove_chars('Hello, World!', ' ,') == 'HelloWorld'",
    "assert remove_chars('"This is a test"', '"') == '"Thisisatest"'",
    "assert remove_chars('/* This is a comment */', '/', ['/', '*']) == ''",
    "assert remove_chars('No comments here', '#', ['#']) == 'No comments here'",
    "assert remove_chars('Tabs	and spaces', '	 ') == 'Tabsandspaces'"
  ]
}

{
  "tests": [
    "assert remove_chars('Hello, World!', chars='o') == 'Hell, Wrld!'",
    "assert remove_chars('"This is a test"', quotes='') == '"This is a test"'",
    "assert remove_chars('// This is a comment', comments='//') == ''",
    "assert remove_chars('/* This is a comment */', chars=' ', quotes='', comments=['/*', '*/']) == '/**/'",
    "assert remove_chars('No special characters here', chars='') == 'No special characters here'"
  ]
}

{
  "tests": [
    "assert remove_chars('Hello, World!', chars='o') == 'Hell, Wrld!'",
    "assert remove_chars('"This is a test"', quotes='') == '"This is a test"'",
    "assert remove_chars('# This is a comment', comments='#') == ''",
    "assert remove_chars('/* This is a comment */', chars=' ', quotes='', comments=['/', '*']) == '/* This is a comment */'",
    "assert remove_chars('No special characters here', chars='') == 'No special characters here'"
  ]
}

