        "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'c')], {'a': [1], 'b': [2]}) == False",
        "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b'), ('b',)], {'a': [1], 'b': [2]}) == True",
        "assert checkFormulas({'a': 1, 'b': 2}, [('a', 'b', 'c')], {'a': [(1, 2)]}) == False"
