  "tests": [
    "assert bound_line_in_box(10, 10, 5, 5, 1, 0, 3) == (False, 8, 5)",
    "assert bound_line_in_box(10, 10, 5, 5, -1, 0, -2) == (None, -5, -5)",
    "assert bound_line_in_box(10, 10, 5, 5, 0, 1, 3) == (False, 5, 8)",
    "assert bound_line_in_box(10, 10, 5, 5, 0, -1, -2) == (None, -5, -5)",
    "assert bound_line_in_box(10, 10, 5, 5, 1, 1, math.sqrt(2)) == (True, 10, 10)"
  ]
}

