{
  "tests": [
    "assert unmet_compare({}, {}) == (0, 'No new dependency problems')",
    "assert unmet_compare({'pkg1': ['dep1']}, {'pkg1': ['dep1', 'dep2']}) == (2, 'Package pkg1 gained new dependency dep2 ')",
    "assert unmet_compare({'pkg1': ['dep1']}, {'pkg2': ['dep2']}) == (3, 'Solved some dependency problems, but created others\nNew problems are \n	pkg2 depends on dep2 \nOld problems were \n	pkg1 depends on dep1 ')",
    "assert unmet_compare({'pkg1': ['dep1'], 'pkg2': ['dep2']}, {'pkg1': ['dep3'], 'pkg2': ['dep2']}) == (1, 'pkg1 swapped unmet dependencies\ngained dep3\nlost dep1')",
    "assert unmet_compare({'pkg1': ['dep1']}, {'pkg1': ['dep1'], 'pkg2': ['dep2']}) == (4, 'New packages with dependency problems \n	pkg2 depends on dep2 ')"
  ]
}

