{
  "tests": [
    "assert Merge([1, 2, 3, 4], 0, 1, 2, None) == ['Increasing', 1]",
    "assert Merge([4, 3, 2, 1], 0, 1, 2, None) == ['Decreasing', 4]",
    "assert Merge([1, 3, 2, 4], 0, 1, 2, ['Increasing', 1]) == ['Specific Minima', 2]",
    "assert Merge([4, 2, 3, 1], 0, 1, 2, ['Decreasing', 4]) == ['Specific Maxima', 3]",
    "assert Merge([1, 2, 2, 3], 0, 1, 2, ['Increasing', 1]) == ['Maxima', 2]"
  ]
}

{
  "tests": [
    "assert Merge([1, 2, 3, 4], 0, 1, 2, None) == ['Increasing', 1]",
    "assert Merge([4, 3, 2, 1], 0, 1, 2, None) == ['Decreasing', 4]",
    "assert Merge([1, 3, 2, 4], 0, 1, 2, ['Increasing', 1]) == ['Specific Minima', 2]",
    "assert Merge([4, 2, 3, 1], 0, 1, 2, ['Decreasing', 4]) == ['Specific Maxima', 3]",
    "assert Merge([1, 2, 3, 4], 0, 1, 2, ['Maxima', 3]) == ['Maxima', 3]"
  ]
}

{
  "tests": [
    "assert Merge([1, 2, 3, 4], 0, 1, 2, None) == ['Increasing', 1]",
    "assert Merge([4, 3, 2, 1], 0, 1, 2, None) == ['Decreasing', 4]",
    "assert Merge([1, 3, 2, 4], 0, 1, 2, ['Increasing', 1]) == ['Specific Minima', 2]",
    "assert Merge([4, 2, 3, 1], 0, 1, 2, ['Decreasing', 4]) == ['Specific Maxima', 3]",
    "assert Merge([1, 2, 3, 4], 0, 1, 2, ['Maxima', 3]) == ['Maxima', 3]"
  ]
}

{
  "tests": [
    "assert Merge([3, 2, 1], 0, 1, 2, [None, None]) == [None, 3]",
    "assert Merge([1, 2, 3], 0, 1, 2, [None, None]) == [None, 1]",
    "assert Merge([1, 3, 2], 0, 1, 2, [None, None]) == [None, 3]",
    "assert Merge([3, 1, 2], 0, 1, 2, [None, None]) == [None, 3]",
    "assert Merge([1, 2, 3], 0, 1, 2, [None, 1]) == [None, 1]"
  ]
}

{
  "tests": [
    "assert Merge([1, 3, 2, 4], 0, 1, 2, [None, None]) == [None, None]",
    "assert Merge([5, 4, 3, 2], 0, 1, 2, [None, None]) == ['Decreasing', 4]",
    "assert Merge([1, 2, 3, 4], 0, 1, 2, [None, None]) == ['Increasing', 1]",
    "assert Merge([1, 2, 3, 4], 0, 1, 2, ['Maxima', 3]) == ['Specific Maxima case', 4]",
    "assert Merge([5, 4, 3, 2], 0, 1, 2, ['Minima', 2]) == ['Specific Minima', 3]"
  ]
}

